import {evaluate,parseJD} from "./engine.js";
const KEYS={profile:"career-os-v1-profile",queue:"career-os-v1-queue",theme:"career-os-v1-theme"},state={profile:null,meta:null,extraction:null,result:null,queue:[]},$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=v=>String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c])),labels={TAILOR_AND_APPLY:"TAILOR + APPLY",FAST_APPLY:"FAST APPLY",MANUAL_REVIEW:"MANUAL REVIEW",SKIP:"SKIP"};
function toast(m){const e=$("#toast");e.textContent=m;e.classList.add("show");setTimeout(()=>e.classList.remove("show"),2400)}function step(n){$$('.step-panel').forEach(x=>x.classList.toggle("active",+x.dataset.panel===n));$$('.steps li').forEach(x=>x.classList.toggle("active",+x.dataset.step<=n));location.hash="analyze"}function data(f){return Object.fromEntries(new FormData(f).entries())}function fill(f,d){for(const[k,v]of Object.entries(d||{}))if(f.elements[k])f.elements[k].value=v}function saveProfile(p){state.profile=p;localStorage.setItem(KEYS.profile,JSON.stringify(p))}
function renderExtraction(){const x=state.extraction;$("#extraction-review").innerHTML=`<div class="review-grid"><div class="review-card wide"><h4>Detected skills</h4><p>Uncheck anything that is not genuinely required. Add missing requirements below.</p><div class="chips">${[...x.required,...x.preferred].map(s=>`<label class="check-chip"><input type="checkbox" value="${esc(s)}" ${x.required.includes(s)?"checked":""}><span>${esc(s)}</span></label>`).join("")||'<span class="muted">No known skills detected—add them manually.</span>'}</div><div class="inline-add"><input id="new-requirement" placeholder="Add a missing skill"><button class="button ghost" id="add-requirement" type="button">Add</button></div></div><label>Minimum years<input id="review-years" type="number" min="0" max="30" value="${x.minYears}"></label><label>Seniority<select id="review-seniority">${["unspecified","intern","early-career","senior","staff"].map(v=>`<option ${v===x.seniority?"selected":""}>${v}</option>`).join("")}</select></label><label>Work setting<select id="review-setting">${["unspecified","remote","hybrid","onsite"].map(v=>`<option ${v===x.workSetting?"selected":""}>${v}</option>`).join("")}</select></label><label class="sensitive-check"><input id="review-sensitive" type="checkbox" ${x.sensitive?"checked":""}><span><b>Sensitive eligibility language needs manual review</b><small>Keep checked if the JD mentions sponsorship, visas, citizenship, or authorization.</small></span></label></div>`;$("#add-requirement").onclick=()=>{const v=$("#new-requirement").value.trim().toLowerCase();if(v){state.extraction.required=[...new Set([...state.extraction.required,v])];renderExtraction()}}}
function approved(){return{...state.extraction,required:$$('.check-chip input:checked').map(x=>x.value),preferred:[],minYears:+$("#review-years").value||0,seniority:$("#review-seniority").value,workSetting:$("#review-setting").value,sensitive:$("#review-sensitive").checked}}
function renderDecision(){const r=state.result,m=state.meta;$("#decision").innerHTML=`<div class="result-head" data-route="${r.route}"><div><p class="eyebrow">Recommended route</p><span class="result-route">${labels[r.route]}</span><h3>${esc(m.role)}</h3><p>${esc(m.company||"Unlabeled opportunity")}</p></div><div class="score-ring"><strong>${r.score}</strong><span>fit score</span></div></div><div class="component-grid">${Object.entries(r.components).map(([k,v])=>`<div><span>${esc(k)}</span><b>${v}</b><i style="--value:${v/(k==='skills'?45:k==='role'?20:k==='domain'?15:10)*100}%"></i></div>`).join("")}</div><div class="result-grid"><article><h4>Why</h4><ul>${r.reasons.map(x=>`<li>${esc(x)}</li>`).join("")}</ul></article><article><h4>Open gaps</h4><ul>${r.gaps.length?r.gaps.map(x=>`<li>${esc(x)}</li>`).join(""):'<li>No material gap detected by this limited parser.</li>'}</ul></article><article><h4>Supported matches</h4><ul>${r.evidenceMatches.length?r.evidenceMatches.map(x=>`<li><b>${esc(x.skill)}</b>${x.notes.length?`<small>${x.notes.map(esc).join(" · ")}</small>`:""}</li>`).join(""):'<li>No skill match identified.</li>'}</ul></article><article><h4>Human questions</h4><ul>${r.manualQuestions.length?r.manualQuestions.map(x=>`<li>${esc(x)}</li>`).join(""):'<li>No sensitive question detected. Verify the source before acting.</li>'}</ul></article></div><div class="disclaimer">Deterministic text matching—not legal advice, an employability prediction, or a guarantee.</div>`}
function persist(){localStorage.setItem(KEYS.queue,JSON.stringify(state.queue))}function renderQueue(){const el=$("#job-list");$("#queue-count").textContent=`${state.queue.length} saved ${state.queue.length===1?"opportunity":"opportunities"}`;if(!state.queue.length){el.innerHTML='<div class="empty"><span>＋</span><h3>Your queue is empty.</h3><p>Analyze a real JD above or use the sample to complete the flow.</p><a class="button primary" href="#analyze">Analyze a JD</a></div>';return}el.innerHTML=[...state.queue].sort((a,b)=>b.score-a.score).map(j=>`<article class="queue-card" data-route="${j.route}"><div><p class="company">${esc(j.company||"Unlabeled")}</p><h3>${esc(j.role)}</h3><p>${labels[j.route]} · ${j.score}/100 · ${esc(j.createdAt.slice(0,10))}</p></div><div class="queue-actions"><select data-status="${esc(j.id)}" aria-label="Application status">${["considering","preparing","applied","archived"].map(v=>`<option ${j.status===v?"selected":""}>${v}</option>`).join("")}</select><button class="icon-button" data-remove="${esc(j.id)}" aria-label="Remove opportunity">×</button></div></article>`).join("");$$('[data-status]').forEach(x=>x.onchange=()=>{state.queue.find(j=>j.id===x.dataset.status).status=x.value;persist()});$$('[data-remove]').forEach(x=>x.onclick=()=>{state.queue=state.queue.filter(j=>j.id!==x.dataset.remove);persist();renderQueue()})}
$("#profile-form").onsubmit=e=>{e.preventDefault();saveProfile(data(e.currentTarget));step(2)};$("#jd-form").onsubmit=e=>{e.preventDefault();const d=data(e.currentTarget);state.meta={company:d.company.trim(),role:d.role.trim()};state.extraction=parseJD(d.jd,d.role);renderExtraction();step(3)};$("#evaluate").onclick=()=>{state.extraction=approved();state.result=evaluate(state.profile,state.extraction,state.meta);renderDecision();step(4)};$("#add-to-queue").onclick=()=>{state.queue=[{id:crypto.randomUUID(),...state.meta,score:state.result.score,route:state.result.route,reasons:state.result.reasons,gaps:state.result.gaps,status:"considering",createdAt:new Date().toISOString()},...state.queue];persist();renderQueue();toast("Added to your browser-local queue.");location.hash="queue"};$("#restart").onclick=()=>{$("#jd-form").reset();step(2)};$$('.back').forEach(b=>b.onclick=()=>step(+b.dataset.back));
$("#load-sample-profile").onclick=()=>fill($("#profile-form"),{roles:"Applied AI Engineer, Machine Learning Engineer",skills:"Python, SQL, machine learning, data pipelines, model evaluation, Docker, Git",years:"2",location:"remote",domains:"healthcare, life sciences",evidence:"Built a Python data pipeline with regression tests\nEvaluated machine learning model quality\nTranslated stakeholder needs into software requirements"});$("#load-sample-jd").onclick=()=>fill($("#jd-form"),{company:"Example Health Systems",role:"Applied AI Engineer",jd:"We are seeking an early-career Applied AI Engineer to build reliable healthcare automation. Required: Python, SQL, machine learning, data pipelines, Docker, model evaluation, and cross-functional stakeholder work. Candidates should have at least 2 years of project or professional experience. Experience with AWS and observability is preferred. This is a remote role in the United States. Applicants will be asked work authorization questions during the application process."});
$("#export").onclick=()=>{const a=document.createElement("a"),payload={version:1,exportedAt:new Date().toISOString(),profile:state.profile,queue:state.queue};a.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:"application/json"}));a.download="career-os-local-export.json";a.click();URL.revokeObjectURL(a.href);toast("Export created locally.")};$("#import-button").onclick=()=>$("#import-file").click();$("#import-file").onchange=async e=>{try{const d=JSON.parse(await e.target.files[0].text());if(d.version!==1||!Array.isArray(d.queue))throw 0;state.profile=d.profile||null;state.queue=d.queue;saveProfile(state.profile||{});persist();fill($("#profile-form"),state.profile);renderQueue();toast("Local export imported.")}catch{toast("That file is not a valid Career OS export.")}e.target.value=""};$("#clear-data").onclick=()=>{if(confirm("Delete the anonymous profile and every saved opportunity from this browser?")){Object.values(KEYS).forEach(k=>localStorage.removeItem(k));state.profile=null;state.queue=[];$("#profile-form").reset();renderQueue();toast("All Career OS data was removed.")}};$("#theme").onclick=()=>{const n=document.documentElement.dataset.theme==="dark"?"light":"dark";document.documentElement.dataset.theme=n;localStorage.setItem(KEYS.theme,n)};
document.documentElement.dataset.theme=localStorage.getItem(KEYS.theme)||"light";state.profile=JSON.parse(localStorage.getItem(KEYS.profile)||"null");state.queue=JSON.parse(localStorage.getItem(KEYS.queue)||"[]");if(state.profile)fill($("#profile-form"),state.profile);renderQueue();
